WITH base AS (SELECT * FROM subscriptions WHERE start_date < '2025-09-01' AND (monthly_fee IS NULL OR end_date > '2023-11-01')), summary AS (SELECT CASE WHEN monthly_fee >= 243 THEN 'high' WHEN monthly_fee >= 77 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, status, SUM(monthly_fee) AS total_monthly_fee FROM base GROUP BY CASE WHEN monthly_fee >= 243 THEN 'high' WHEN monthly_fee >= 77 THEN 'mid' ELSE 'low' END, status) SELECT monthly_fee_bucket, status, total_monthly_fee FROM summary WHERE total_monthly_fee < 700;
